WITH scored AS (SELECT *, LAST_VALUE(quantity, TRUE) OVER (PARTITION BY order_id, product_id ORDER BY unit_price, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_quantity, COUNT(unit_price) OVER (PARTITION BY order_id) AS order_id_count_unit_price FROM order_items WHERE quantity = 3) SELECT s.id, s.order_id, s.quantity, s.unit_price, s.order_id_count_unit_price, (SELECT AVG(x.cost) FROM shipments x WHERE x.order_id = s.order_id) AS avg_shipment_cost FROM scored s ORDER BY order_id_count_unit_price DESC, avg_shipment_cost
